{
  "name": "@varonell/ai-usage",
  "version": "1.7.8",
  "description": "Desktop and terminal usage meters for Claude Code, Codex CLI, OpenCode, and Claude.ai",
  "main": "main.js",
  "bin": {
    "ai-usage": "usage-cli.js",
    "ccusage-widget": "usage-cli.js"
  },
  "scripts": {
    "start": "electron .",
    "build": "electron-builder",
    "build:win": "electron-builder --win",
    "dev": "cross-env NODE_ENV=development electron .",
    "build:mac": "electron-builder --mac",
    "build:linux": "electron-builder --linux",
    "usage": "node usage-cli.js",
    "test": "node test/evidence-log.test.js && node test/provider-tracking.test.js && node test/slot-planner.test.js && node test/window-controls.test.js && node test/window-lifecycle.test.js && node test/desktop-companion.test.js && node test/windows-installer-config.test.js",
    "test:providers": "node test/provider-tracking.test.js",
    "test:evidence": "node test/evidence-log.test.js"
  },
  "keywords": [
    "claude",
    "codex",
    "opencode",
    "terminal",
    "usage",
    "widget",
    "electron"
  ],
  "author": "Varonell",
  "license": "MIT",
  "copyright": "Copyright © 2025 Slavomir Durej",
  "engines": {
    "node": ">=18.0.0",
    "npm": ">=9.0.0"
  },
  "devDependencies": {
    "@electron/notarize": "^3.1.1",
    "cross-env": "^7.0.3",
    "electron": "^41.10.1",
    "electron-builder": "^26.15.3"
  },
  "dependencies": {
    "chart.js": "^4.5.1",
    "electron-store": "^8.1.0"
  },
  "build": {
    "appId": "com.claudeusage.widget",
    "productName": "AI Usage",
    "copyright": "Copyright © 2025 Slavomir Durej",
    "publish": null,
    "win": {
      "target": [
        "nsis",
        "portable"
      ],
      "icon": "assets/icon.ico",
      "legalTrademarks": "Varonell"
    },
    "portable": {
      "artifactName": "AI-Usage-${version}-win-portable.${ext}",
      "unpackDirName": "ai-usage"
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "createDesktopShortcut": true,
      "createStartMenuShortcut": true,
      "artifactName": "AI-Usage-${version}-win-Setup.${ext}",
      "include": "build/installer.nsh"
    },
    "files": [
      "**/*",
      "!**/*.ts",
      "!*.md",
      "!**/.env*",
      "!**/{auth,credentials,secrets}.json",
      "!**/*.{pem,key,p12,pfx,jks,keystore}"
    ],
    "mac": {
      "target": [
        {
          "target": "dmg",
          "arch": [
            "arm64",
            "x64"
          ]
        }
      ],
      "icon": "assets/icon.icns",
      "hardenedRuntime": true,
      "gatekeeperAssess": false,
      "entitlements": "build/entitlements.mac.plist",
      "entitlementsInherit": "build/entitlements.mac.plist",
      "notarize": true,
      "extendInfo": {
        "NSHumanReadableCopyright": "Copyright © 2025 Slavomir Durej"
      }
    },
    "dmg": {
      "artifactName": "AI-Usage-${version}-macOS-${arch}.dmg"
    },
    "linux": {
      "executableName": "ai-usage",
      "target": [
        {
          "target": "AppImage",
          "arch": [
            "x64",
            "arm64"
          ]
        }
      ],
      "icon": "assets/logo.png",
      "category": "Utility",
      "artifactName": "AI-Usage-${version}-linux-${arch}.${ext}"
    }
  }
}
